CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE profiles(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,data jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resumes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL,structured_data jsonb NOT NULL,object_key text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE skills(id bigserial PRIMARY KEY,name text UNIQUE NOT NULL);
CREATE TABLE job_preferences(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),canonical_url text UNIQUE NOT NULL,company text NOT NULL,title text NOT NULL,location text,description text,source text,posted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE job_matches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,score int NOT NULL CHECK(score BETWEEN 0 AND 100),details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,job_id));
CREATE TYPE application_status AS ENUM('discovered','prepared','applied','in_review','interview','rejected','offer','withdrawn');
CREATE TABLE applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,job_id uuid NOT NULL REFERENCES jobs(id),resume_id uuid REFERENCES resumes(id),status application_status NOT NULL DEFAULT 'discovered',match_score int CHECK(match_score BETWEEN 0 AND 100),applied_at timestamptz,notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,job_id));
CREATE TABLE application_answers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES applications(id) ON DELETE CASCADE,question text NOT NULL,answer text NOT NULL,approved_by_user boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE application_events(id bigserial PRIMARY KEY,application_id uuid NOT NULL REFERENCES applications(id) ON DELETE CASCADE,event_type text NOT NULL,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,job_id uuid REFERENCES jobs(id),read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_company_title_idx ON jobs(lower(company),lower(title));CREATE INDEX applications_user_status_idx ON applications(user_id,status);CREATE INDEX events_application_created_idx ON application_events(application_id,created_at DESC);
